  ('pcp','tramadol','dangerous','','pcp|tramadol'),
  ('pregabalin','tramadol','unsafe','There is a significant risk of seizures. Both substances are CNS depressants, potentiating each other strongly and unpredictably, raising the chances of memory loss, severe ataxia, and unconsciousness. The interaction will cause greater inhibition and risk of injury. If the user falls unconscious it is strongly recommended to put them into the recovery position and monitor breathing. Medical dosages are not reported to be a concern.','pregabalin|tramadol'),
  ('ssris','tramadol','dangerous','','ssris|tramadol')
) as v(a,b,status,note,pair)
join public.unified_tags ta on ta.slug = v.a
join public.unified_tags tb on tb.slug = v.b
where ta.id <> tb.id
on conflict (tag_a_id, tag_b_id) do update
  set status = excluded.status, note = excluded.note,
      source = excluded.source, source_url = excluded.source_url,
      source_pair = excluded.source_pair, updated_at = now();

do $verify$
declare v_n int; v_d int; v_notes int; v_bad int; v_digest text;
begin
  select count(*), count(*) filter (where status='dangerous'), count(note)
    into v_n, v_d, v_notes from public.substance_interactions;
  if v_n <> 421 then raise exception 'interactions: expected 421 pairs, got %', v_n; end if;
  if v_d  <> 82  then raise exception 'interactions: expected 82 dangerous, got %', v_d; end if;
  if v_notes <> 221 then raise exception 'interactions: expected 221 notes, got %', v_notes; end if;

  -- Spot-check two cells where being wrong is fatal, by SLUG rather than by
  -- position, so a remapping cannot quietly satisfy the count checks above.
  if not exists (select 1 from public.substance_interactions i
      join public.unified_tags a on a.id=i.tag_a_id join public.unified_tags b on b.id=i.tag_b_id
     where i.status='dangerous' and array['ghb','opioids'] <@ array[a.slug,b.slug]) then
    raise exception 'interactions: GHB + opioids is not dangerous - mapping is wrong'; end if;
  if not exists (select 1 from public.substance_interactions i
      join public.unified_tags a on a.id=i.tag_a_id join public.unified_tags b on b.id=i.tag_b_id
     where i.status='dangerous' and array['mdma','maois'] <@ array[a.slug,b.slug]) then
    raise exception 'interactions: MDMA + MAOIs is not dangerous - mapping is wrong'; end if;

  select count(*) into v_bad from public.substance_interactions
   where source is null or source_url is null or source = '';
  if v_bad > 0 then raise exception 'interactions: % rows without attribution', v_bad; end if;

  -- Content fingerprint. Counts and spot-checks can all pass while a single
  -- note or status is wrong; this cannot. Byte order (collate "C") is required
  -- so the digest matches the generator, which sorts by Unicode code point.
  select encode(sha256(convert_to(string_agg(line, chr(30) order by line collate "C"),'UTF8')),'hex')
    into v_digest
    from (select least(a.slug,b.slug)||chr(31)||greatest(a.slug,b.slug)||chr(31)
                 ||i.status||chr(31)||coalesce(i.note,'') as line
            from public.substance_interactions i
            join public.unified_tags a on a.id=i.tag_a_id
            join public.unified_tags b on b.id=i.tag_b_id) s;
  if v_digest <> '3b6768cc649dc2868c3451dee07b202c043cdad4d64b7ad22c101f9805fb5142' then
    raise exception 'interactions: content digest % does not match the imported snapshot', v_digest;
  end if;
end
$verify$;
